// Orden de los grupos como en los gráficos de la tesis; dentro de cada grupo, por número (DVC y después Lhôte).
const ORDEN = ["tesalio", "beocio", "severior", "dorico", "doricoNO", "jonicoAtico", "mezcla", "noJonAt", "sinClasificar"];
const num = (id) => (id.startsWith("LOD ") ? 10000 : 0) + parseInt(id.replace(/\D/g, ""), 10);
export const AUTOPSIAS_DATA = ORDEN.flatMap((d) =>
  [...FICHAS, ...FICHAS_2025].filter((a) => a.dialect === d).sort((a, b) => num(a.id) - num(b.id)));
